package com.aydindemir.redis.service; import java.util.Set; import org.springframework.data.redis.core.*; import org.springframework.stereotype.Service; import com.aydindemir.redis.redis.cache.KeyNamingService;
@Service public class LeaderboardService { private final StringRedisTemplate redis; private final KeyNamingService keys; public LeaderboardService(StringRedisTemplate r,KeyNamingService k){redis=r;keys=k;} public void addScore(String b,String u,double s){redis.opsForZSet().add(keys.key("leaderboard",b),u,s);} public Set<ZSetOperations.TypedTuple<String>> top(String b,long c){return redis.opsForZSet().reverseRangeWithScores(keys.key("leaderboard",b),0,Math.max(0,c-1));} }
